; where.asm -- chapter 12: 256 calls, timed with the stack in two places
; generated by gen12.py
        INCLUDE "msx.inc"
        OUTPUT "where.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; 256 calls of an empty routine, timed three times: with the stack at
; SYS_AREA and the display off; with the stack at SYS_AREA while the VDP
; draws the picture; and with the stack at $C800, low in the RAM, while it
; draws the picture.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
w1:     call calls              ; the display off, the stack at SYS_AREA
w2:     VDP_REG 1, $E0          ; the display on, and its interrupt
        im 1
        ei
        halt                    ; the picture has just ended
        di
        call wait               ; on into the next one
w3:     call calls              ; while it is drawn, the stack at SYS_AREA
w4:     ld sp, $C800            ; the stack low in the RAM
        ei
        halt
        di
        call wait
w5:     call calls              ; while it is drawn, the stack at $C800
w6:     nop
stop:   jr stop

; calls: 256 calls of a routine that returns at once
calls:  ld b, 0
ca1:    call empty
        djnz ca1
        ret
empty:  ret

; wait: 1000 turns of 30 T-states
wait:   ld bc, 1000
wa1:    dec bc
        ld a, b
        or c
        jr nz, wa1
        ret

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
